{
  "name": "MedBot - AI Medical Assistant",
  "description": "A medical chatbot that recommends doctors based on patient symptoms and provides quick medical advice. The chatbot can communicate in English, Sinhala, and Tamil."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat, GenerateContentResponse } from '@google/genai';
import { Language, Message, Doctor } from './types';
import { SYSTEM_PROMPT_TEMPLATE, LANGUAGE_OPTIONS, INITIAL_GREETINGS } from './constants';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import LanguageSelector from './components/LanguageSelector';
import Header from './components/Header';
import Disclaimer from './components/Disclaimer';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [language, setLanguage] = useState<Language>(Language.EN);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [chat, setChat] = useState<Chat | null>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Scroll to the bottom of the chat container when messages change
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages]);

  const initializeChat = useCallback(() => {
    try {
      if (!process.env.API_KEY) {
        throw new Error("API_KEY environment variable not set");
      }
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const systemInstruction = SYSTEM_PROMPT_TEMPLATE.replace('{language}', language);

      const newChat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: systemInstruction,
        },
      });
      setChat(newChat);

      const greeting = INITIAL_GREETINGS[language];

      setMessages([
        {
          id: 'initial-greeting',
          role: 'bot',
          text: greeting,
        }
      ]);
    } catch (error) {
       console.error("Failed to initialize chat:", error);
       setMessages([{ id: 'error-init', role: 'bot', text: 'Error: Could not initialize AI chat. Please check the API key and refresh.' }]);
    }
  }, [language]);

  useEffect(() => {
    initializeChat();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [language]);

  const handleSendMessage = async (inputText: string) => {
    if (!inputText.trim() || isLoading || !chat) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      text: inputText,
    };
    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setIsLoading(true);

    let fullResponseText = '';
    const botMessageId = (Date.now() + 1).toString();

    try {
      const stream = await chat.sendMessageStream({ message: inputText });

      // Create a placeholder for the bot's message
      setMessages((prev) => [...prev, { id: botMessageId, role: 'bot', text: '...' }]);

      for await (const chunk of stream) {
        const c = chunk as GenerateContentResponse;
        fullResponseText += c.text;

        // Update the bot's message in real-time
        setMessages((prev) =>
          prev.map((msg) =>
            msg.id === botMessageId ? { ...msg, text: fullResponseText } : msg
          )
        );
      }

      const recommendationPrefix = 'DOCTOR_RECOMMENDATION::';
      let doctor: Doctor | undefined;
      let finalText = fullResponseText;

      if (fullResponseText.startsWith(recommendationPrefix)) {
          const jsonString = fullResponseText.substring(recommendationPrefix.length);
          try {
              const doctorData: Doctor = JSON.parse(jsonString);
              doctor = doctorData;
              finalText = `${doctorData.reason}`;
          } catch (e) {
              console.error("Failed to parse doctor recommendation JSON:", e);
              finalText = fullResponseText; // Fallback to showing raw response
          }
      }

      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === botMessageId ? { ...msg, text: finalText, doctor } : msg
        )
      );

    } catch (error) {
      console.error('Error sending message:', error);
      const errorMessage = 'Sorry, I encountered an error. Please try again.';
      setMessages((prev) => 
         prev.map((msg) => msg.id === botMessageId ? {...msg, text: errorMessage} : msg)
      );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen font-sans bg-gray-50 dark:bg-gray-900 text-gray-800 dark:text-gray-200">
      <Header />
      <LanguageSelector
        selectedLanguage={language}
        onLanguageChange={(lang: Language) => {
          setLanguage(lang);
        }}
        languages={LANGUAGE_OPTIONS}
      />
      <Disclaimer />
      <div
        ref={chatContainerRef}
        className="flex-1 overflow-y-auto p-4 space-y-4"
      >
        {messages.map((msg) => (
          <ChatMessage key={msg.id} message={msg} />
        ))}
        {isLoading && messages[messages.length-1].role === 'user' && (
           <ChatMessage key="loading" message={{id: 'loading', role: 'bot', text: '...'}} />
        )}
      </div>
      <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700">
        <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

export default App;

export enum Language {
  EN = 'English',
  SI = 'Sinhala',
  TA = 'Tamil',
}

export type Role = 'user' | 'bot';

export interface Doctor {
  specialty: string;
  reason: string;
}

export interface Message {
  id: string;
  role: Role;
  text: string;
  doctor?: Doctor;
}

import { Language } from './types';

export const LANGUAGE_OPTIONS: { value: Language; label: string, shortLabel: string }[] = [
  { value: Language.EN, label: 'English', shortLabel: 'EN' },
  { value: Language.SI, label: 'Sinhala (සිංහල)', shortLabel: 'SI' },
  { value: Language.TA, label: 'Tamil (தமிழ்)', shortLabel: 'TA' },
];

export const SYSTEM_PROMPT_TEMPLATE = `
You are MedBot, a helpful and empathetic AI medical assistant. 
Your primary goal is to understand a user's medical symptoms and recommend a type of doctor (e.g., Cardiologist, Dermatologist, General Practitioner).
You must converse fluently in the user's chosen language, which is currently set to: {language}.

RULES:
1.  When you identify a clear need for a specific doctor, you MUST format your response with a special prefix: \`DOCTOR_RECOMMENDATION::\`. This prefix must be followed by a single, valid JSON object with two keys: "specialty" (string) and "reason" (string).
    Example: DOCTOR_RECOMMENDATION::{"specialty": "Cardiologist", "reason": "Based on your symptoms of chest pain and shortness of breath, a cardiologist is the appropriate specialist to consult."}
2.  For all other queries, provide general, non-emergency medical advice. Keep your answers quick, straightforward, and easy to understand.
3.  Do NOT diagnose any condition. You are not a doctor.
4.  CRITICAL SAFETY WARNING: Always include a disclaimer that the user should consult a real medical professional for diagnosis and treatment. If symptoms sound severe or like an emergency, strongly advise them to contact local emergency services immediately. Your advice is for informational purposes only.
5.  Always respond in {language}.
`;

export const INITIAL_GREETINGS: Record<Language, string> = {
  [Language.EN]: "Hello! I'm MedBot, your AI medical assistant. How can I help you today? Please describe your symptoms.",
  [Language.SI]: "ආයුබෝවන්! මම මෙඩ්බොට්, ඔබේ AI වෛද්‍ය සහායක. අද ඔබට උදව් කළ හැක්කේ කෙසේද? කරුණාකර ඔබේ රෝග ලක්ෂණ විස්තර කරන්න.",
  [Language.TA]: "வணக்கம்! நான் மெட்பாட், உங்கள் AI மருத்துவ உதவியாளர். இன்று நான் உங்களுக்கு எப்படி உதவ முடியும்? உங்கள் அறிகுறிகளை விவரிக்கவும்.",
};

import React from 'react';
import { Message } from '../types';
import DoctorCard from './DoctorCard';

interface ChatMessageProps {
  message: Message;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isTyping = message.text === '...';

  const wrapperClasses = `flex items-end gap-2 ${isUser ? 'justify-end' : 'justify-start'}`;
  const bubbleClasses = `max-w-md lg:max-w-2xl px-4 py-3 rounded-2xl break-words ${
    isUser
      ? 'bg-blue-600 text-white rounded-br-none'
      : 'bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-bl-none'
  }`;

  return (
    <div className={wrapperClasses}>
      {!isUser && (
        <div className="flex-shrink-0 w-8 h-8 bg-gray-300 dark:bg-gray-600 rounded-full flex items-center justify-center text-white font-bold text-sm">
          AI
        </div>
      )}
      <div className="flex flex-col">
        <div className={bubbleClasses}>
            {isTyping ? (
                 <div className="flex items-center justify-center space-x-1">
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.3s'}}></div>
                 </div>
            ) : (
                <p className="whitespace-pre-wrap">{message.text}</p>
            )}
        </div>
        {message.doctor && (
            <div className="mt-2">
                <DoctorCard doctor={message.doctor} />
            </div>
        )}
      </div>
    </div>
  );
};

export default ChatMessage;

import React, { useState, useRef } from 'react';

interface ChatInputProps {
  onSendMessage: (message: string) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setText(e.target.value);
    // Auto-resize textarea
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() && !isLoading) {
      onSendMessage(text);
      setText('');
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e as unknown as React.FormEvent);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="flex items-center space-x-3">
      <textarea
        ref={textareaRef}
        value={text}
        onChange={handleInputChange}
        onKeyDown={handleKeyPress}
        placeholder="Type your symptoms here..."
        className="flex-1 p-3 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none bg-gray-50 dark:bg-gray-700 text-gray-800 dark:text-gray-200 resize-none max-h-40"
        rows={1}
        disabled={isLoading}
      />
      <button
        type="submit"
        disabled={isLoading || !text.trim()}
        className="px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 flex items-center justify-center"
      >
        {isLoading ? (
          <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
        ) : (
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 12 3.269 3.125A59.769 59.769 0 0 1 21.485 12 59.768 59.768 0 0 1 3.27 20.875L5.999 12Zm0 0h7.5" />
          </svg>
        )}
      </button>
    </form>
  );
};

export default ChatInput;

import React from 'react';
import { Language } from '../types';

interface LanguageSelectorProps {
  selectedLanguage: Language;
  onLanguageChange: (language: Language) => void;
  languages: { value: Language; label: string; shortLabel: string }[];
}

const LanguageSelector: React.FC<LanguageSelectorProps> = ({ selectedLanguage, onLanguageChange, languages }) => {
  return (
    <div className="flex justify-center p-2 bg-gray-100 dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
      <div className="flex space-x-2 bg-white dark:bg-gray-900 p-1 rounded-lg shadow-sm">
        {languages.map(({ value, label, shortLabel }) => (
          <button
            key={value}
            onClick={() => onLanguageChange(value)}
            className={`px-3 py-1.5 text-sm font-medium rounded-md transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-900 ${
              selectedLanguage === value
                ? 'bg-blue-600 text-white shadow'
                : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
            aria-pressed={selectedLanguage === value}
            title={`Switch to ${label}`}
          >
           <span className="sm:hidden">{shortLabel}</span>
           <span className="hidden sm:inline">{label}</span>
          </button>
        ))}
      </div>
    </div>
  );
};

export default LanguageSelector;

import React from 'react';
import { Doctor } from '../types';

interface DoctorCardProps {
  doctor: Doctor;
}

const DoctorCard: React.FC<DoctorCardProps> = ({ doctor }) => {
  return (
    <div className="max-w-md bg-blue-50 dark:bg-blue-900/30 border border-blue-200 dark:border-blue-800 rounded-lg p-4 mt-2">
      <div className="flex items-center space-x-3">
        <div className="flex-shrink-0 bg-blue-100 dark:bg-blue-900 text-blue-600 dark:text-blue-300 rounded-full p-2">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 6a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0ZM4.501 20.118a7.5 7.5 0 0 1 14.998 0A17.933 17.933 0 0 1 12 21.75c-2.676 0-5.216-.584-7.499-1.632Z" />
          </svg>
        </div>
        <div>
          <p className="text-sm text-blue-600 dark:text-blue-300 font-semibold">Recommendation</p>
          <h3 className="text-lg font-bold text-gray-800 dark:text-gray-100">{doctor.specialty}</h3>
        </div>
      </div>
    </div>
  );
};

export default DoctorCard;

import React from 'react';

const Header: React.FC = () => {
  return (
    <header className="p-4 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 shadow-sm">
      <div className="flex items-center space-x-3">
        <div className="p-2 bg-blue-600 rounded-full">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5.121 17.804A13.937 13.937 0 0112 16c2.5 0 4.847.655 6.879 1.804M15 10a3 3 0 11-6 0 3 3 0 016 0zm6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
        </div>
        <h1 className="text-xl font-bold text-gray-800 dark:text-white">MedBot AI Assistant</h1>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';

const Disclaimer: React.FC = () => {
  return (
    <div className="p-2 bg-yellow-100 dark:bg-yellow-900/30 border-b border-yellow-200 dark:border-yellow-800 text-center">
      <p className="text-xs text-yellow-800 dark:text-yellow-200">
        <span className="font-bold">Disclaimer:</span> MedBot is an AI assistant and not a substitute for professional medical advice. Always consult a doctor for diagnosis. In case of an emergency, call your local emergency services.
      </p>
    </div>
  );
};

export default Disclaimer;
